 supervised:['Supervised learning','Supervised learning fits relationships using labeled examples.'],unsupervised:['Unsupervised learning','Unsupervised learning discovers structure without supplied target labels.'],probabilistic:['Probabilistic behavior','Model outputs can vary or express statistical rather than deterministic relationships.'],generalize:['Generalization','Generalization is useful performance on representative examples beyond training.'],oracle:['Test-oracle problem','A test oracle is difficult when the exact correct output is unknown or costly to determine.'],human:['Human oversight','A human review point can constrain consequential actions while retaining accountability.'],robust:['Robustness','Robustness concerns acceptable behavior under relevant variation and disturbance.'],fair:['Subgroup fairness evaluation','Group-specific evaluation can reveal disparities concealed by aggregate results.'],explain:['Explainability','Explainability concerns understandable factors or reasons behind model behavior.'],calibrate:['Calibration','Calibration compares predicted confidence with observed outcome frequencies.'],safety:['Risk-based acceptance criteria','Acceptance criteria should reflect consequences, affected populations and intended use.'],accuracy:['Accuracy','Accuracy counts correct predictions across all evaluated cases.'],precision:['Precision','Precision is true positives divided by predicted positives.'],recall:['Recall','Recall is true positives divided by actual positives.'],f1:['F1 score','F1 is the harmonic mean of precision and recall, with its own trade-offs and limits.'],mae:['Mean absolute error','MAE averages absolute differences between numerical predictions and targets.'],confusion:['Confusion matrix','A confusion matrix separates true and false predictions by actual and predicted classes.'],imbalance:['Class-imbalance analysis','A dominant class can conceal poor performance on a rare important class.'],threshold:['Decision-threshold evaluation','Changing a decision threshold changes the balance of false positives and false negatives.'],metamorphic:['Metamorphic testing','Metamorphic testing checks expected relationships among transformed inputs and outputs.'],differential:['Differential testing','Differential testing compares implementations but disagreement does not by itself identify the correct result.'],adversarial:['Adversarial robustness testing','Adversarial tests challenge behavior with inputs designed to expose weaknesses.'],abstain:['Abstention or fallback behavior','An explicit fallback can handle uncertain or unsupported cases without pretending certainty.'],repeat:['Repeated evaluation','Repeated trials help characterize variability rather than assuming one run is representative.'],
